// Perfil desde PostgreSQL via /api/profiles/runtime. El backend ya resuelve
// keywords, include_terms, ubicacion e idioma desde el catalogo del
// personalizador, asi que aqui solo se pasa el contrato adelante.
const p = $('Perfil (API)').first().json.profile || {};
return [{ json: { profile: {
  idioma: p.idioma || 'es',
  keywords: p.keywords || 'Engineer,Analyst,Operations',
  include_terms: Array.isArray(p.include_terms) ? p.include_terms : [],
  location: p.location || '',
  perfil_texto: p.perfil_texto || '',
} } }];

// El scraper devuelve { ok, source, jobs: [...] }. Un item por oferta.
const r = $input.first().json || {};
const jobs = Array.isArray(r.jobs) ? r.jobs : [];
const source = r.source || 'desconocido';
if (jobs.length === 0) {
  return [{ json: { __sinOfertas: true, motivo: 'el scraper no devolvió ofertas (source: ' + source + ')', source } }];
}
return jobs.map((j) => ({ json: { ...j, source } }));

// Filtro guiado por el PERFIL: mantiene ofertas cuyo título/empresa encaja
// con los términos derivados de sector_interes + formacion del usuario.
// EXCLUDE es fijo (basura que nunca interesa).
const prof = $('Cargar perfil').first().json.profile;
const INCLUDE = (prof.include_terms && prof.include_terms.length)
  ? prof.include_terms
  : ['engineer', 'analyst', 'developer', 'software', 'data', 'operations', 'project', 'consultant'];
const EXCLUDE = ['sales representative', 'account executive', 'call center', 'teleoperador', 'camarero',
  'waiter', 'kitchen', 'limpieza', 'cleaner', 'conductor', 'repartidor', 'mozo de almacen',
  'beca no remunerada', 'unpaid', 'comercial telefonico'];
const noAcc = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

const pass = [];
for (const item of $input.all()) {
  const j = item.json;
  if (j.__sinOfertas) { pass.push({ json: j }); continue; }
  const hay = noAcc((j.title || '') + ' ' + (j.company || '') + ' ' + (j.descriptionSnippet || ''));
  if (EXCLUDE.some((w) => hay.includes(w))) continue;
  const matched = INCLUDE.filter((w) => hay.includes(w));
  if (matched.length === 0) continue;
  pass.push({ json: { ...j, __matched: matched.slice(0, 6) }, pairedItem: item.pairedItem });
}
return pass;

const store = $getWorkflowStaticData('global');
const seen = store.jobsSeen || {};
const now = Date.now();
const TTL = 21 * 24 * 60 * 60 * 1000;
for (const k of Object.keys(seen)) { if (now - seen[k] > TTL) delete seen[k]; }

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (j.__sinOfertas) { out.push({ json: j }); continue; }
  const key = (j.link || (j.title + '|' + j.company)).toLowerCase().trim();
  if (!key || seen[key]) continue;
  seen[key] = now;
  out.push({ json: j, pairedItem: item.pairedItem });
}
store.jobsSeen = seen;
return out;

// Puntuación determinista 0-100. Incluye un ajuste por encaje con el perfil.
const noAcc = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const ROLE_SCORES = { 'aerospace':30,'aeroespacial':30,'space':25,'espacio':25,'artificial intelligence':25,'inteligencia artificial':25,'machine learning':22,'automation':20,'digital transformation':20,'supply chain':18,'industrial engineer':18,'project manager':16,'project engineer':16,'program manager':15,'data':15,'operations':14,'business analyst':14,'consultant':13,'strategy':13,'software':12,'manufacturing':12,'logistics':11,'planning':11,'engineering':9,'engineer':7 };
const PRIORITY = ['airbus','boeing','indra','thales','gmv','sener','esa','nasa','spacex','siemens','honeywell','accenture','capgemini','mckinsey','bcg','deloitte','pwc','kpmg','ey','amazon','google','microsoft','sap','seat','nvidia','ibm'];
const JUNIOR = ['junior','graduate','trainee','intern','becario','entry level','associate','young talent'];

const includeTerms = $('Cargar perfil').first().json.profile.include_terms || [];

function scoreOne(j) {
  const hay = noAcc((j.title || '') + ' ' + (j.descriptionSnippet || ''));
  const company = noAcc(j.company || '');
  let s = 5;
  for (const [k, v] of Object.entries(ROLE_SCORES)) if (hay.includes(k)) s += v;
  if (PRIORITY.some((c) => company.includes(c))) s += 20;
  if (JUNIOR.some((k) => hay.includes(k))) s += 10;
  const perfilHits = includeTerms.filter((t) => hay.includes(t)).length;
  s += Math.min(perfilHits * 6, 24);
  if (j.postedAt) {
    const days = (Date.now() - new Date(j.postedAt).getTime()) / 86400000;
    if (days <= 3) s += 8; else if (days <= 7) s += 4;
  }
  return Math.max(0, Math.min(100, Math.round(s)));
}

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (j.__sinOfertas) { out.push({ json: j }); continue; }
  out.push({ json: { ...j, score: scoreOne(j) }, pairedItem: item.pairedItem });
}
return out;

const MIN_SCORE = 15;
const MAX = 3;
const rows = $input.all().map((i) => i.json).filter((j) => !j.__sinOfertas);
const top = rows
  .filter((j) => (j.score || 0) >= MIN_SCORE)
  .sort((a, b) => (b.score || 0) - (a.score || 0))
  .slice(0, MAX);
if (top.length === 0) {
  return [{ json: { __sinOfertas: true, motivo: 'ninguna oferta nueva superó el umbral de relevancia', evaluadas: rows.length } }];
}
return top.map((j) => ({ json: j }));

