// Lee la respuesta del Automation Center (/api/ai/generate).
// `data` ya viene parseado; `text` es el respaldo. Se acepta ademas el sobre
// antiguo de Gemini para que una importacion a medias no falle en silencio.
function leerIA(r) {
  if (!r) return null;
  if (r.data && typeof r.data === 'object') return r.data;
  const crudo = typeof r.text === 'string'
    ? r.text
    : (r.candidates && r.candidates[0] && r.candidates[0].content
       && r.candidates[0].content.parts && r.candidates[0].content.parts[0]
       && r.candidates[0].content.parts[0].text);
  if (!crudo) return null;
  return JSON.parse(String(crudo).replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, ''));
}

// Une (por índice) cada oferta del TOP 3 con su resumen de la IA.
// No depende de pairedItem: TOP 3 y la IA mantienen el mismo orden y nº de items.
const jobs = $('Seleccionar TOP 3').all().map((i) => i.json).filter((j) => !j.__sinOfertas);
const resp = $input.all().map((i) => i.json);
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const out = [];
for (let i = 0; i < jobs.length; i++) {
  const job = jobs[i];
  let g = {};
  try { g = leerIA(resp[i]) || {}; } catch (e) {}
  out.push({ json: {
    title: esc(job.title || 'Oferta'),
    company: esc(job.company || '—'),
    location: esc(job.location || '—'),
    score: job.score || 0,
    link: job.link || '',
    source: job.source || '',
    resumen: esc(g.resumen || 'Resumen no disponible (la IA no devolvió datos).'),
    motivo_fit: esc(g.motivo_fit || ''),
  } });
}
return out;

// Un mensaje con el TOP de ofertas de hoy (los campos ya vienen escapados).
const items = $input.all().map((i) => i.json);
if (items.length === 0) return [];
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Telegram rechaza mensajes de mas de 4096 caracteres. Se parte por bloques
// completos (nunca a mitad de una etiqueta HTML) y se numeran las partes.
function trocear(cabecera, bloques, pie, max = 3900) {
  const SEP = '\n\n━━━━━━━━━━\n\n';
  const partes = [];
  let actual = cabecera;
  let primero = true;
  for (const b of bloques) {
    const candidato = primero ? actual + b : actual + SEP + b;
    if (!primero && candidato.length > max) { partes.push(actual); actual = b; }
    else actual = candidato;
    primero = false;
  }
  if ((actual + pie).length > max) { partes.push(actual); actual = pie.trim(); }
  else actual += pie;
  partes.push(actual);
  return partes.map((texto, i) => ({ json: {
    texto: partes.length > 1 ? texto + '\n<i>(' + (i + 1) + '/' + partes.length + ')</i>' : texto,
  } }));
}
const prof = $('Cargar perfil').first().json.profile;
const fecha = new Date().toLocaleDateString('es-ES', { weekday: 'long', day: 'numeric', month: 'long' });

const bloques = items.map((o, i) =>
  `<b>${i + 1}. ${o.title}</b>\n🏢 ${o.company}  ·  📍 ${o.location}\n⭐ ${o.score}/100  ·  fuente: ${esc(o.source)}\n\n${o.resumen}` +
  (o.motivo_fit ? `\n🎯 ${o.motivo_fit}` : '') +
  (o.link ? `\n🔗 <a href="${esc(o.link)}">Ver oferta</a>` : '')
);

const busqueda = [prof.keywords, prof.location].filter(Boolean).map(esc).join(' · ');
return trocear(
  `💼 <b>OFERTAS DEL DÍA</b>\n<i>${fecha}</i>\n` + (busqueda ? `<i>${busqueda}</i>\n` : '') + `\n━━━━━━━━━━\n\n`,
  bloques,
  `\n\n━━━━━━━━━━\n<i>${items.length} oferta(s), las mejores por puntuación</i>`,
);

